"""
    Evaluates the predicted chunk accuracy
    :param predicted:
    :return:
    """
def eval(predicted: Any) -> object {
    word_cnt = 0;
    correct = 0;
    for sentence in predicted {
        for row in sentence {
            word_cnt += 1;
            if (row['chunk'] == row['pchunk']) {
                correct += 1;
            }
        }
    }
    return (correct / word_cnt);
}

"""get number of groups used by GroupNorm, based on number of channels."""
def get_group_gn(dim: Any, dim_per_gp: Any, num_groups: Any) -> object {
    assert ((dim_per_gp == -1) or (num_groups == -1)) , "GroupNorm: can only specify G or C/G.";
    if (dim_per_gp > 0) {
        assert ((dim % dim_per_gp) == 0) , "dim: {}, dim_per_gp: {}".format(
            dim, dim_per_gp
        );
        group_gn = dim // dim_per_gp;
    } else {
        assert ((dim % num_groups) == 0) , "dim: {}, num_groups: {}".format(
            dim, num_groups
        );
        group_gn = num_groups;
    }
    return group_gn;
}

"""
    This is a utility method to replace null or empty values with a replacement value

    :param dictionary: A dict of values
    :param replacement_value: a value to be used as a substitute for nulls/empties, such as "--"
    :return: a dict with null/empty values replaced
    """
def replace_null_values(dictionary: Any, replacement_value: Any) -> object {
    clean_dictionary = {};
    if ((dictionary is None) and not dictionary) {
        return clean_dictionary;
    }
    for key in dictionary {
        if (dictionary[key] in ('null', 'UNKNOWN', 'unknown', None, 'None')) {
            clean_dictionary[key] = replacement_value;
        } else {
            clean_dictionary[key] = dictionary[key];
        }
    }
    return clean_dictionary;
}

