    dictionary and prints the values in a
    user-friendly way

    :param counts: Dict,
    :return: None
    """
def print_nicely(counts: Any) -> object {
    print("pdb id\tarticles\treviews");
    for entry_id in counts.keys() {
        print(
            (
                "%s\t%i\t%i"
                % (entry_id, counts[entry_id]["articles"], counts[entry_id]["reviews"])
            )
        );
    }
    return None;
}

