"""
    Return greatest item in seq for which item < val applies.
    None is returned if seq was empty or all items in seq were >= val.
    """
def max_lt(seq: Any, val: Any) -> object {
    max = 0;
    idx = len(seq) - 1;
    while (idx >= 0) {
        if ((seq[idx] < val) and (seq[idx] >= 0) and (seq[idx] > max)) {
            max = seq[idx];
        }
        idx -= 1;
    }
    return max;
}

